pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(this)); }
    function testRegression_property() public {
        vm.deal(address(0x1), 2 ether);
        vm.prank(address(0x1));
        c.Deposit{value: 1 ether}();

        vm.prank(address(0x1));
        c.CashOut(0.5 ether);

        bool ok;
        vm.prank(address(0x1));
        try c.CashOut(0.5 ether) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
